        [mskom1m100,~,msk800_om1m1_vertex] = draw_mask(wm800_om1m1);
        cuts2fit800.mask_ds2 = msk800_om1m1_vertex;
    else
        [mskom1m100,~,msk800_om1m1_vertex] = draw_mask(wm800_om1m1,'mask',cuts2fit800.mask_ds2');
    end
    wm800_om1m1 = mask(wm800_om1m1,mskom1m100); %[output:8be3b214]
    plot(wm800_om1m1); lz 0 0.5;keep_figure %[output:898e2ff9]

    % Cut 3
    wm_800o11 = cut(w2_800o11,[-2,0.04,3],[]);
    plot(wm_800o11); lz 0 0.5; %[output:323e136c]
    if ~exist('cuts2fit800','var')
        [msko11,~,msk800_o11_vertex] = draw_mask(wm_800o11);
        wm_800o11  = mask(wm_800o11,msko11)
        [msko11b,~,msk800_o11_vertex1] = draw_mask(wm_800o11);        
        plot(wm_800o11 ); lz 0 0.5
        [msko11c,~,msk800_o11_vertex2] = draw_mask(wm_800o11);        
        wm_800o11  = mask(wm_800o11,msko11c)
        plot(wm_800o11 ); lz 0 0.5; keep_figure
    else
        [msko11,~,msk800_o11_vertex] = draw_mask(wm_800o11,'mask',cuts2fit800.mask_ds3{1}');
        wm_800o11  = mask(wm_800o11,msko11)         %[output:7f8e55ea]
        [msko11b,~,msk800_o11_vertex1] = draw_mask(wm_800o11,'mask',cuts2fit800.mask_ds3{2}'); 
        wm_800o11  = mask(wm_800o11,msko11b)         %[output:1f602381]
        [msko11c,~,msk800_o11_vertex2] = draw_mask(wm_800o11,'mask',cuts2fit800.mask_ds3{3}');        
        wm_800o11  = mask(wm_800o11,msko11c)    %[output:921c5786]
        plot(wm_800o11 ); lz 0 0.5; keep_figure         %[output:323e136c]
    end

    cuts2fit800=struct('cuts_list',[], ... %[output:517e69ca]
        'mask_ds1',{msk800o00_vertex}, ... %[output:517e69ca]
        'mask_ds2',{msk800_om1m1_vertex}, ... %[output:517e69ca]
        'mask_ds3',[]); %[output:517e69ca]
    cuts2fit800.cuts_list = {wm800_o00,wm800_om1m1,wm_800o11};
    cuts2fit800.mask_ds3 = {msk800_o11_vertex,msk800_o11_vertex1,msk800_o11_vertex2};
end %[output:group:79357e89]
